import{A as d}from"./aos-2f37143e.js";import{_ as t,b as i,o as s,c as v,a as e}from"./index-da40e78e.js";const o="/resume/assets/p03-efc699d0.jpg";const l={class:"autobiography"},_={__name:"Autobiography",setup(c){return i(()=>{d.init()}),(r,a)=>(s(),v("div",l,a[0]||(a[0]=[e('<h1 class="auto_title" data-aos="fade-left" data-aos-duration="1000" data-v-d0d77068>AUTOBIOGRAPHY</h1><div class="auto_mains" data-v-d0d77068><div class="auto_title_main" data-aos="fade-up" data-aos-duration="2000" data-v-d0d77068><div class="title_wrap" data-v-d0d77068><div class="title_line1" data-v-d0d77068></div><h2 class="auto_main_title" data-v-d0d77068>關於我</h2><div class="title_line2" data-v-d0d77068></div></div><h4 class="auto_main_tec" data-v-d0d77068>我是黃意晴，畢業於文化大學廣告系，主修廣告行銷企劃。畢業後，我在影音行銷領域累積了五年經驗，參與過新媒體、服飾品牌、經紀公司、牙醫、政治、YouTube 等多元產業，從企劃、拍攝到剪輯皆有豐富實戰經驗。影音產業的工作讓我培養了良好的團隊合作能力、敏銳的流行趨勢嗅覺，以及快速學習新技術的習慣，也能夠在緊湊的排程中有效完成專案。</h4></div><div class="auto_title_main" data-aos="fade-up" data-aos-duration="2000" data-aos-delay="300" data-v-d0d77068><div class="title_wrap" data-v-d0d77068><div class="title_line1" data-v-d0d77068></div><h2 class="auto_main_title" data-v-d0d77068>轉職契機</h2><div class="title_line2" data-v-d0d77068></div></div><h4 class="auto_main_tec" data-v-d0d77068>起初，我因為想架設作品集網站而接觸了 Wix，進而對網頁設計產生興趣。在深入研究後，我對前端工程師的工作內容產生強烈憧憬，於是報名了 Tibame 的前端工程師課程，進行為期四個月的系統性學習。這段期間，我透過 HTML、CSS、JavaScript 等技術，獨立開發了個人作品集網站，使作品集能以更具設計感的方式呈現。此外，我的個人專題為「攝影工作室網站」，負責從 UI 設計到前端開發，強化了我的切版能力與互動設計技巧。</h4></div><div class="auto_title_main" data-aos="fade-up" data-aos-duration="2000" data-v-d0d77068><div class="title_wrap" data-v-d0d77068><div class="title_line1" data-v-d0d77068></div><h2 class="auto_main_title" data-v-d0d77068>專題表現</h2><div class="title_line2" data-v-d0d77068></div></div><h4 class="auto_main_tec" data-v-d0d77068>在期末團體專題中，我有幸擔任組長，負責時程規劃與團隊溝通。我們的專案使用 Vue 框架開發，主題為「沉浸式體驗活動平台」，提供使用者瀏覽三種不同主題的活動，並具備預約與周邊商品購買功能。後端則使用 PHP 和 MySQL 進行資料庫管理。<br data-v-d0d77068> 我負責的前端開發部分包括：<br data-v-d0d77068><br data-v-d0d77068> ・網站前導頁 - 使用 jQuery 設計滑鼠滾動觸發的文字與圖片互動效果。<br data-v-d0d77068><br data-v-d0d77068> ・首頁輪播 - 透過 Swiper 套件實現活動入口輪播，並運用 CSS 動畫增強視覺效果。<br data-v-d0d77068> ・「人生賭場」活動頁面 - 負責 UI 設計與切版，並使用一頁式滾動與動畫營造賭場氛圍。<br data-v-d0d77068> ・最新消息 - 依據 UI 設計進行切版，搭配 AOS 套件增強畫面・動態效果，並使用 JavaScript 完成分頁與彈窗功能。<br data-v-d0d77068><br data-v-d0d77068> 後端部分包括：<br data-v-d0d77068><br data-v-d0d77068> ・商品頁 - 透過 PHP 串接 MySQL 資料庫，動態顯示商品資訊並支援後台管理。 ・訂票流程 - 使用 Pinia 儲存會員資料，完成後將訂單資訊同步至會員中心與後台。 ・最新消息管理 - 可在後台進行消息的新增與修改。<br data-v-d0d77068><br data-v-d0d77068> 最後，由我負責整合組員開發的前後端功能，並將專案部署至伺服器，完整呈現網站功能。</h4></div><div class="auto_title_main" data-aos="fade-up" data-aos-duration="2000" data-v-d0d77068><div class="title_wrap" data-v-d0d77068><div class="title_line1" data-v-d0d77068></div><h2 class="auto_main_title" data-v-d0d77068>個人特質</h2><div class="title_line2" data-v-d0d77068></div></div><h4 class="auto_main_tec" data-v-d0d77068>我的主管和團隊過去最認可我的是高效解決問題的能力，每當面對新挑戰，我會優先查找資料並主動提出可行解決方案，減少團隊負擔。<br data-v-d0d77068> 我擁有強大的自學能力，過去能從零開始學習剪輯，並成為影音產業的一員，如今也以同樣的熱情投入前端領域。多年影音行銷的經歷培養了我的抗壓性、專案管理能力與美感經驗，相信這些優勢能幫助我在前端開發的道路上發揮更大價值。我期待能與團隊共同成長，運用前端技術創造更優秀的使用者體驗，並持續學習新技術，為未來開發更具創意與挑戰性的專案做好準備！</h4></div></div><img class="autobiography_photo" src="'+o+'" alt="" data-aos="fade-up" data-aos-duration="2000" data-v-d0d77068>',3)])))}},p=t(_,[["__scopeId","data-v-d0d77068"]]);export{p as default};
